#![forbid(unsafe_code)]
//! GGUF's block formats: their sizes and a host decoder for each.
//!
//! Hub GGUF files mix these per tensor, including ggml's codebook formats that Candle does
//! not know, so [`BlockFormat`] names everything a Tur projection can read as stored. The
//! device decoder is `block_weights8` in `quantized.metal`; both are checked against values
//! generated by ggml itself (`scripts/gguf_blocks_reference.py`).

#![allow(
    clippy::many_single_char_names,
    clippy::suboptimal_flops,
    reason = "decoders keep ggml's names and exact arithmetic, against which they are checked"
)]

use crate::block_tables::{
    IQ1S_GRID, IQ2S_GRID, IQ2XS_GRID, IQ2XXS_GRID, IQ3S_GRID, IQ3XXS_GRID, KSIGNS, KVALUES_FP4,
    KVALUES_IQ4NL,
};
use candle_core::quantized::GgmlDType;
use tur_core::{Result, execution::invalid};

/// ggml's fixed offset of IQ1 quants from their grid points.
const IQ1_DELTA: f32 = 0.125;

/// One tensor's stored element or block type. Discriminants select the decoder through
/// the `BLOCK_FORMAT` function constant in `quantized.metal`.
#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub enum BlockFormat {
    F32 = 0,
    F16 = 1,
    Bf16 = 2,
    Q4_0 = 3,
    Q4_1 = 4,
    Q5_0 = 5,
    Q5_1 = 6,
    Q8_0 = 7,
    Q2K = 8,
    Q3K = 9,
    Q4K = 10,
    Q5K = 11,
    Q6K = 12,
    Iq1S = 13,
    Iq1M = 14,
    Iq2Xxs = 15,
    Iq2Xs = 16,
    Iq2S = 17,
    Iq3Xxs = 18,
    Iq3S = 19,
    Iq4Nl = 20,
    Iq4Xs = 21,
    Mxfp4 = 22,
}

impl BlockFormat {
    /// Every format, in discriminant order.
    pub const ALL: [Self; 23] = [
        Self::F32,
        Self::F16,
        Self::Bf16,
        Self::Q4_0,
        Self::Q4_1,
        Self::Q5_0,
        Self::Q5_1,
        Self::Q8_0,
        Self::Q2K,
        Self::Q3K,
        Self::Q4K,
        Self::Q5K,
        Self::Q6K,
        Self::Iq1S,
        Self::Iq1M,
        Self::Iq2Xxs,
        Self::Iq2Xs,
        Self::Iq2S,
        Self::Iq3Xxs,
        Self::Iq3S,
        Self::Iq4Nl,
        Self::Iq4Xs,
        Self::Mxfp4,
    ];

    /// The format of a `ggml_type` value, or `None` for types no projection can read.
    pub fn from_ggml(ggml_type: u32) -> Option<Self> {
        Some(match ggml_type {
            0 => Self::F32,
            1 => Self::F16,
            2 => Self::Q4_0,
            3 => Self::Q4_1,
            6 => Self::Q5_0,
            7 => Self::Q5_1,
            8 => Self::Q8_0,
            10 => Self::Q2K,
            11 => Self::Q3K,
            12 => Self::Q4K,
            13 => Self::Q5K,
            14 => Self::Q6K,
            16 => Self::Iq2Xxs,
            17 => Self::Iq2Xs,
            18 => Self::Iq3Xxs,
            19 => Self::Iq1S,
            20 => Self::Iq4Nl,
            21 => Self::Iq3S,
            22 => Self::Iq2S,
            23 => Self::Iq4Xs,
            29 => Self::Iq1M,
            30 => Self::Bf16,
            39 => Self::Mxfp4,
            _ => return None,
        })
    }

    /// Name as llama.cpp spells it.
    pub fn name(self) -> &'static str {
        match self {
            Self::F32 => "F32",
            Self::F16 => "F16",
            Self::Bf16 => "BF16",
            Self::Q4_0 => "Q4_0",
            Self::Q4_1 => "Q4_1",
            Self::Q5_0 => "Q5_0",
            Self::Q5_1 => "Q5_1",
            Self::Q8_0 => "Q8_0",
            Self::Q2K => "Q2_K",
            Self::Q3K => "Q3_K",
            Self::Q4K => "Q4_K",
            Self::Q5K => "Q5_K",
            Self::Q6K => "Q6_K",
            Self::Iq1S => "IQ1_S",
            Self::Iq1M => "IQ1_M",
            Self::Iq2Xxs => "IQ2_XXS",
            Self::Iq2Xs => "IQ2_XS",
            Self::Iq2S => "IQ2_S",
            Self::Iq3Xxs => "IQ3_XXS",
            Self::Iq3S => "IQ3_S",
            Self::Iq4Nl => "IQ4_NL",
            Self::Iq4Xs => "IQ4_XS",
            Self::Mxfp4 => "MXFP4",
        }
    }

    /// Values one block holds.
    pub fn block_values(self) -> usize {
        match self {
            Self::F32 | Self::F16 | Self::Bf16 => 1,
            Self::Q4_0
            | Self::Q4_1
            | Self::Q5_0
            | Self::Q5_1
            | Self::Q8_0
            | Self::Iq4Nl
            | Self::Mxfp4 => 32,
            _ => 256,
        }
    }

    /// Stored bytes of one block.
    pub fn block_bytes(self) -> usize {
        match self {
            Self::F32 => 4,
            Self::F16 | Self::Bf16 => 2,
            Self::Q4_0 | Self::Iq4Nl => 18,
            Self::Mxfp4 => 17,
            Self::Q4_1 => 20,
            Self::Q5_0 => 22,
            Self::Q5_1 => 24,
            Self::Q8_0 => 34,
            Self::Iq1S => 50,
            Self::Iq1M => 56,
            Self::Iq2Xxs => 66,
            Self::Iq2Xs => 74,
            Self::Iq2S => 82,
            Self::Q2K => 84,
            Self::Iq3Xxs => 98,
            Self::Q3K | Self::Iq3S => 110,
            Self::Iq4Xs => 136,
            Self::Q4K => 144,
            Self::Q5K => 176,
            Self::Q6K => 210,
        }
    }

    /// Stored bytes of a `[rows, cols]` matrix, whose rows must tile into whole blocks.
    pub fn bytes(self, rows: usize, cols: usize) -> Result<usize> {
        let values = self.block_values();
        if cols == 0 || !cols.is_multiple_of(values) {
            return Err(invalid(format!(
                "{cols} columns do not tile into {} blocks",
                self.name()
            )));
        }
        rows.checked_mul(cols / values)
            .and_then(|blocks| blocks.checked_mul(self.block_bytes()))
            .ok_or_else(|| invalid("block size overflows"))
    }

    /// The block format equivalent to a Candle format.
    pub fn from_candle(format: GgmlDType) -> Option<Self> {
        Self::ALL
            .into_iter()
            .find(|block| block.candle() == Some(format))
    }

    /// The equivalent Candle format, whose kernels and host conversions can also read it.
    pub fn candle(self) -> Option<GgmlDType> {
        Some(match self {
            Self::Q4_0 => GgmlDType::Q4_0,
            Self::Q4_1 => GgmlDType::Q4_1,
            Self::Q5_0 => GgmlDType::Q5_0,
            Self::Q5_1 => GgmlDType::Q5_1,
            Self::Q8_0 => GgmlDType::Q8_0,
            Self::Q2K => GgmlDType::Q2K,
            Self::Q3K => GgmlDType::Q3K,
            Self::Q4K => GgmlDType::Q4K,
            Self::Q5K => GgmlDType::Q5K,
            Self::Q6K => GgmlDType::Q6K,
            _ => return None,
        })
    }

    /// Whether `cols` tile into 32-value chunks of this format, as the device kernels read.
    pub fn tiles(self, cols: usize) -> bool {
        cols.is_multiple_of(32) && cols.is_multiple_of(self.block_values())
    }

    /// Row-major F32 values of a `[_, cols]` matrix in this format.
    pub fn decode(self, bytes: &[u8], cols: usize) -> Result<Vec<f32>> {
        let block_bytes = self.block_bytes();
        let values = self.block_values();
        if !bytes.len().is_multiple_of(block_bytes) || !cols.is_multiple_of(values) {
            return Err(invalid(format!(
                "{} bytes do not form whole {} blocks",
                bytes.len(),
                self.name()
            )));
        }
        let mut out = vec![0.0; bytes.len() / block_bytes * values];
        for (block, out) in bytes
            .chunks_exact(block_bytes)
            .zip(out.chunks_exact_mut(values))
        {
            self.decode_block(block, out);
        }
        Ok(out)
    }

    fn decode_block(self, b: &[u8], y: &mut [f32]) {
        match self {
            Self::F32 => y[0] = f32::from_le_bytes([b[0], b[1], b[2], b[3]]),
            Self::F16 => y[0] = half16(b, 0),
            Self::Bf16 => {
                y[0] = f32::from_bits(u32::from(u16::from_le_bytes([b[0], b[1]])) << 16);
            }
            Self::Q4_0 | Self::Q4_1 | Self::Q5_0 | Self::Q5_1 => legacy(self, b, y),
            Self::Q8_0 => {
                let d = half16(b, 0);
                for (y, &q) in y.iter_mut().zip(&b[2..]) {
                    *y = f32::from(q.cast_signed()) * d;
                }
            }
            Self::Q2K => q2k(b, y),
            Self::Q3K => q3k(b, y),
            Self::Q4K => q4k(b, y),
            Self::Q5K => q5k(b, y),
            Self::Q6K => q6k(b, y),
            Self::Iq1S | Self::Iq1M => iq1(self, b, y),
            Self::Iq2Xxs | Self::Iq2Xs | Self::Iq2S => iq2(self, b, y),
            Self::Iq3Xxs | Self::Iq3S => iq3(self, b, y),
            Self::Iq4Nl => {
                let d = half16(b, 0);
                for j in 0..16 {
                    y[j] = d * f32::from(KVALUES_IQ4NL[usize::from(b[2 + j] & 15)]);
                    y[j + 16] = d * f32::from(KVALUES_IQ4NL[usize::from(b[2 + j] >> 4)]);
                }
            }
            Self::Iq4Xs => iq4xs(b, y),
            Self::Mxfp4 => {
                // E8M0 scale halved, because the table holds doubled E2M1 values.
                let d = 2f32.powi(i32::from(b[0]) - 128);
                for j in 0..16 {
                    y[j] = d * f32::from(KVALUES_FP4[usize::from(b[1 + j] & 15)]);
                    y[j + 16] = d * f32::from(KVALUES_FP4[usize::from(b[1 + j] >> 4)]);
                }
            }
        }
    }
}

fn half16(b: &[u8], at: usize) -> f32 {
    half_bits(u16::from_le_bytes([b[at], b[at + 1]]))
}

/// IEEE binary16 to F32, as ggml's scales are stored.
fn half_bits(bits: u16) -> f32 {
    let sign = u32::from(bits >> 15) << 31;
    let exponent = u32::from(bits >> 10) & 31;
    let mantissa = u32::from(bits & 1023);
    let magnitude = match (exponent, mantissa) {
        (0, 0) => 0,
        (0, m) => {
            // Subnormal: normalize into F32's wider exponent range.
            let shift = m.leading_zeros() - 21;
            ((113 - shift) << 23) | (((m << shift) & 1023) << 13)
        }
        (31, m) => (255 << 23) | (m << 13),
        (e, m) => ((e + 112) << 23) | (m << 13),
    };
    f32::from_bits(sign | magnitude)
}

fn u32le(b: &[u8], at: usize) -> u32 {
    u32::from_le_bytes([b[at], b[at + 1], b[at + 2], b[at + 3]])
}

fn u16le(b: &[u8], at: usize) -> usize {
    usize::from(u16::from_le_bytes([b[at], b[at + 1]]))
}

/// `Q4_0`, `Q4_1`, `Q5_0` and `Q5_1`: signed `_0` and offset `_1`, each byte holding two low nibbles.
fn legacy(format: BlockFormat, b: &[u8], y: &mut [f32]) {
    let offset = matches!(format, BlockFormat::Q4_1 | BlockFormat::Q5_1);
    let wide = matches!(format, BlockFormat::Q5_0 | BlockFormat::Q5_1);
    let d = half16(b, 0);
    let m = if offset { half16(b, 2) } else { 0.0 };
    let mut at = if offset { 4 } else { 2 };
    let high = if wide { u32le(b, at) } else { 0 };
    at += if wide { 4 } else { 0 };
    let center = match (offset, wide) {
        (true, _) => 0.0,
        (false, true) => 16.0,
        (false, false) => 8.0,
    };
    for j in 0..16 {
        let q0 = u32::from(b[at + j] & 15) | (((high >> j) & 1) << 4);
        let q1 = u32::from(b[at + j] >> 4) | (((high >> (j + 16)) & 1) << 4);
        y[j] = (q0 as f32 - center) * d + m;
        y[j + 16] = (q1 as f32 - center) * d + m;
    }
}

/// Six-bit scale and minimum of sub-block `j` from `Q4_K` and `Q5_K`'s 12 packed scale bytes.
fn scale_min(s: &[u8], j: usize) -> (f32, f32) {
    if j < 4 {
        (f32::from(s[j] & 63), f32::from(s[j + 4] & 63))
    } else {
        (
            f32::from((s[j + 4] & 15) | ((s[j - 4] >> 6) << 4)),
            f32::from((s[j + 4] >> 4) | ((s[j] >> 6) << 4)),
        )
    }
}

fn q2k(b: &[u8], y: &mut [f32]) {
    let (scales, qs) = (&b[..16], &b[16..80]);
    let (d, min) = (half16(b, 80), half16(b, 82));
    for (e, y) in y.iter_mut().enumerate() {
        let (group, x) = (e / 128, e % 128);
        let q = qs[group * 32 + (x % 32) / 16 * 16 + x % 16] >> (2 * (x / 32));
        let scale = scales[e / 16];
        *y = d * f32::from(scale & 15) * f32::from(q & 3) - min * f32::from(scale >> 4);
    }
}

/// The 16 signed `Q3_K` scales: 4 low bits from the first eight bytes, 2 high from the rest.
fn q3k_scales(s: &[u8]) -> [f32; 16] {
    let [a0, a1, top] = [u32le(s, 0), u32le(s, 4), u32le(s, 8)];
    let word = |low: u32, shift: u32| (low & 0x0f0f_0f0f) | (((top >> shift) & 0x0303_0303) << 4);
    let words = [word(a0, 0), word(a1, 2), word(a0 >> 4, 4), word(a1 >> 4, 6)];
    std::array::from_fn(|i| ((words[i / 4] >> (8 * (i % 4))) & 63) as f32 - 32.0)
}

fn q3k(b: &[u8], y: &mut [f32]) {
    let (hmask, qs) = (&b[..32], &b[32..96]);
    let scales = q3k_scales(&b[96..108]);
    let d = half16(b, 108);
    for (e, y) in y.iter_mut().enumerate() {
        let (group, x) = (e / 128, e % 128);
        let at = (x % 32) / 16 * 16 + x % 16;
        let step = x / 32;
        let q = i32::from((qs[group * 32 + at] >> (2 * step)) & 3);
        let high = hmask[at] & (1 << (group * 4 + step)) != 0;
        *y = d * scales[e / 16] * (q - if high { 0 } else { 4 }) as f32;
    }
}

fn q4k(b: &[u8], y: &mut [f32]) {
    let (d, min) = (half16(b, 0), half16(b, 2));
    let (scales, qs) = (&b[4..16], &b[16..]);
    for (e, y) in y.iter_mut().enumerate() {
        let (scale, minimum) = scale_min(scales, e / 32);
        let q = qs[e / 64 * 32 + e % 32];
        let q = if e % 64 < 32 { q & 15 } else { q >> 4 };
        *y = d * scale * f32::from(q) - min * minimum;
    }
}

fn q5k(b: &[u8], y: &mut [f32]) {
    let (d, min) = (half16(b, 0), half16(b, 2));
    let (scales, high, low) = (&b[4..16], &b[16..48], &b[48..]);
    for (e, y) in y.iter_mut().enumerate() {
        let (scale, minimum) = scale_min(scales, e / 32);
        let q = low[e / 64 * 32 + e % 32];
        let q = if e % 64 < 32 { q & 15 } else { q >> 4 };
        let bit = high[e % 32] >> (e / 32) & 1;
        *y = d * scale * f32::from(q | (bit << 4)) - min * minimum;
    }
}

fn q6k(b: &[u8], y: &mut [f32]) {
    let (low, high, scales) = (&b[..128], &b[128..192], &b[192..208]);
    let d = half16(b, 208);
    for (e, y) in y.iter_mut().enumerate() {
        let (group, x) = (e / 128, e % 128);
        let (step, l) = (x / 32, x % 32);
        let q = low[group * 64 + l + (step % 2) * 32];
        let q = if step < 2 { q & 15 } else { q >> 4 };
        let top = (high[group * 32 + l] >> (2 * step)) & 3;
        let scale = f32::from(scales[group * 8 + l / 16 + 2 * step].cast_signed());
        *y = d * scale * (i32::from(q | (top << 4)) - 32) as f32;
    }
}

fn signed(value: f32, signs: u8, j: usize) -> f32 {
    if signs & (1 << j) != 0 { -value } else { value }
}

fn iq1(format: BlockFormat, b: &[u8], y: &mut [f32]) {
    let grid_value = |index: usize, j: usize| f32::from((IQ1S_GRID[index] >> (8 * j)) as u8 as i8);
    let delta = |negative: bool| if negative { -IQ1_DELTA } else { IQ1_DELTA };
    if format == BlockFormat::Iq1S {
        let d = half16(b, 0);
        for ib in 0..8 {
            let high = u16le(b, 34 + 2 * ib);
            let dl = d * (2 * ((high >> 12) & 7) + 1) as f32;
            for l in 0..4 {
                let index = usize::from(b[2 + ib * 4 + l]) | (((high >> (3 * l)) & 7) << 8);
                for j in 0..8 {
                    y[ib * 32 + l * 8 + j] =
                        dl * (grid_value(index, j) + delta(high & 0x8000 != 0));
                }
            }
        }
        return;
    }
    let sc = |i: usize| u16le(b, 48 + 2 * i);
    let bits = (sc(0) >> 12) | ((sc(1) >> 8) & 0xf0) | ((sc(2) >> 4) & 0xf00) | (sc(3) & 0xf000);
    let d = half_bits(bits as u16);
    for ib in 0..8 {
        let (qs, qh) = (&b[ib * 4..], &b[32 + ib * 2..]);
        for l in 0..4 {
            let byte = qh[l / 2];
            let nibble = if l % 2 == 0 { byte } else { byte >> 4 };
            let index = usize::from(qs[l]) | (usize::from(nibble & 7) << 8);
            let scale = (sc(ib / 2) >> (6 * (ib % 2) + 3 * (l / 2))) & 7;
            let dl = d * (2 * scale + 1) as f32;
            for j in 0..8 {
                y[ib * 32 + l * 8 + j] = dl * (grid_value(index, j) + delta(nibble & 8 != 0));
            }
        }
    }
}

fn iq2(format: BlockFormat, b: &[u8], y: &mut [f32]) {
    let d = half16(b, 0);
    let grid = |table: &[u64], index: usize, j: usize| ((table[index] >> (8 * j)) & 255) as f32;
    for ib in 0..8 {
        for l in 0..4 {
            let (table, index, signs, db): (&[u64], usize, u8, f32) = match format {
                BlockFormat::Iq2Xxs => {
                    let high = u32le(b, 6 + ib * 8);
                    (
                        &IQ2XXS_GRID,
                        usize::from(b[2 + ib * 8 + l]),
                        KSIGNS[((high >> (7 * l)) & 127) as usize],
                        d * (0.5 + (high >> 28) as f32) * 0.25,
                    )
                }
                BlockFormat::Iq2Xs => {
                    let word = u16le(b, 2 + 2 * (4 * ib + l));
                    let scale = b[66 + ib] >> (4 * (l / 2));
                    (
                        &IQ2XS_GRID,
                        word & 511,
                        KSIGNS[word >> 9],
                        d * (0.5 + f32::from(scale & 15)) * 0.25,
                    )
                }
                _ => {
                    let scale = b[74 + ib] >> (4 * (l / 2));
                    let high = (usize::from(b[66 + ib]) << (8 - 2 * l)) & 0x300;
                    (
                        &IQ2S_GRID,
                        usize::from(b[2 + ib * 4 + l]) | high,
                        b[34 + ib * 4 + l],
                        d * (0.5 + f32::from(scale & 15)) * 0.25,
                    )
                }
            };
            for j in 0..8 {
                y[ib * 32 + l * 8 + j] = signed(db * grid(table, index, j), signs, j);
            }
        }
    }
}

fn iq3(format: BlockFormat, b: &[u8], y: &mut [f32]) {
    let d = half16(b, 0);
    let grid = |table: &[u32], index: usize, j: usize| ((table[index] >> (8 * j)) & 255) as f32;
    for ib in 0..8 {
        for l in 0..4 {
            let first = usize::from(b[2 + ib * 8 + 2 * l]);
            let second = usize::from(b[3 + ib * 8 + 2 * l]);
            let (table, first, second, signs, db): (&[u32], usize, usize, u8, f32) =
                if format == BlockFormat::Iq3Xxs {
                    let aux = u32le(b, 66 + 4 * ib);
                    (
                        &IQ3XXS_GRID,
                        first,
                        second,
                        KSIGNS[((aux >> (7 * l)) & 127) as usize],
                        d * (0.5 + (aux >> 28) as f32) * 0.5,
                    )
                } else {
                    let high = usize::from(b[66 + ib]);
                    let scale = (b[106 + ib / 2] >> (4 * (ib % 2))) & 15;
                    (
                        &IQ3S_GRID,
                        first | ((high << (8 - 2 * l)) & 256),
                        second | ((high << (7 - 2 * l)) & 256),
                        b[74 + ib * 4 + l],
                        d * (1 + 2 * u32::from(scale)) as f32,
                    )
                };
            for j in 0..4 {
                y[ib * 32 + l * 8 + j] = signed(db * grid(table, first, j), signs, j);
                y[ib * 32 + l * 8 + j + 4] = signed(db * grid(table, second, j), signs, j + 4);
            }
        }
    }
}

fn iq4xs(b: &[u8], y: &mut [f32]) {
    let d = half16(b, 0);
    let high = u16le(b, 2);
    for ib in 0..8 {
        let low = usize::from((b[4 + ib / 2] >> (4 * (ib % 2))) & 15);
        let scale = low | (((high >> (2 * ib)) & 3) << 4);
        let dl = d * (scale as f32 - 32.0);
        for j in 0..16 {
            let q = b[8 + ib * 16 + j];
            y[ib * 32 + j] = dl * f32::from(KVALUES_IQ4NL[usize::from(q & 15)]);
            y[ib * 32 + j + 16] = dl * f32::from(KVALUES_IQ4NL[usize::from(q >> 4)]);
        }
    }
}

#[cfg(test)]
#[allow(
    clippy::panic_in_result_fn,
    reason = "tests assert outcomes after fallible setup"
)]
mod tests {
    use super::*;

    #[test]
    fn test_block_sizes_reject_rows_that_do_not_tile() -> Result<()> {
        assert_eq!(BlockFormat::Q3K.bytes(3, 512)?, 3 * 2 * 110);
        assert_eq!(BlockFormat::Mxfp4.bytes(1, 64)?, 34);
        assert!(BlockFormat::Q3K.bytes(1, 300).is_err());
        assert!(BlockFormat::Q3K.decode(&[0; 109], 256).is_err());
        assert_eq!(BlockFormat::from_ggml(5), None);
        for (ggml, format) in [(11, BlockFormat::Q3K), (23, BlockFormat::Iq4Xs)] {
            assert_eq!(BlockFormat::from_ggml(ggml), Some(format));
        }
        Ok(())
    }
}
